from typing import List


class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)

        if m < n:
            return 0

        def can(target: int) -> bool:
            need = [(target + p - 1) // p for p in points]

            moves = n
            prev_extra = 0

            for i in range(n - 1):
                required = max(0, need[i] - 1 - prev_extra)
                moves += 2 * required
                if moves > m:
                    return False
                prev_extra = required

            return need[-1] <= 1 + prev_extra

        left, right = 0, max(points) * m
        ans = 0

        while left <= right:
            mid = (left + right) // 2
            if can(mid):
                ans = mid
                left = mid + 1
            else:
                right = mid - 1

        return ans
